export const PieceVersionChecker = ({ snapshot }) => {
  const { releases, pieces } = snapshot;
  const lastIndex = releases.length - 1;

  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [releaseIndex, setReleaseIndex] = useState(lastIndex);

  const normalizedQuery = query.trim().toLowerCase();
  const matches = normalizedQuery.length === 0
    ? []
    : pieces
      .filter(([displayName, name]) => displayName.toLowerCase().includes(normalizedQuery) || name.includes(normalizedQuery))
      .sort(([a], [b]) => Number(!a.toLowerCase().startsWith(normalizedQuery)) - Number(!b.toLowerCase().startsWith(normalizedQuery)))
      .slice(0, 8);

  const choose = (piece) => {
    setSelected(piece);
    setQuery(piece[0]);
    setMenuOpen(false);
  };

  const toPercent = (index) => (index / lastIndex) * 100;
  const ticks = releases
    .map((release, index) => ({ release, index }))
    .filter(({ release, index }) => index === lastIndex || (/^0\.\d0\.0$/.test(release) && lastIndex - index > 15));
  const versionRange = ([first, last, , , count]) => (count === 1 ? first : `${first} – ${last}`);

  const instance = releases[releaseIndex];
  const [displayName, , groups] = selected ?? [null, null, []];
  const isSynced = (group) => group[2] <= releaseIndex && releaseIndex <= group[3];
  const synced = groups.filter(isSynced);
  const newestGroup = groups[groups.length - 1];

  const statusOf = (group) => {
    if (isSynced(group)) return { text: 'synced', on: true };
    if (releaseIndex < group[2]) return { text: `needs ${releases[group[2]]}+`, on: false };
    return { text: `removed after ${releases[group[3]]}`, on: false };
  };

  const summary = () => {
    if (synced.length === 0) {
      return releaseIndex < groups[0][2]
        ? `${displayName} has no versions for ${instance}. It needs ${releases[groups[0][2]]} or newer.`
        : `${displayName} has no versions for ${instance}.`;
    }
    const newestSynced = synced[synced.length - 1][1];
    if (isSynced(newestGroup)) {
      return `On ${instance} you get ${displayName} up to ${newestSynced}, the newest version.`;
    }
    return `On ${instance} the newest ${displayName} version you get is ${newestSynced}. To get ${newestGroup[1]}, upgrade to ${releases[newestGroup[2]]} or newer.`;
  };

  return (
    <div className="vr">
      <div className="vr-search">
        <input
          className="vr-search-input"
          type="text"
          placeholder="Search for a piece, e.g. Gmail"
          value={query}
          onChange={(event) => {
            setQuery(event.target.value);
            setMenuOpen(true);
          }}
          onFocus={() => setMenuOpen(true)}
          onBlur={() => setTimeout(() => setMenuOpen(false), 150)}
          onKeyDown={(event) => {
            if (event.key === 'Enter' && matches.length > 0) choose(matches[0]);
            if (event.key === 'Escape') setMenuOpen(false);
          }}
        />
        {menuOpen && normalizedQuery.length > 0 && (
          <div className="vr-menu">
            {matches.length === 0 && <div className="vr-menu-empty">No piece matches “{query}”.</div>}
            {matches.map((piece) => (
              <button
                type="button"
                className="vr-menu-item"
                key={piece[1]}
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => choose(piece)}
              >
                <span>{piece[0]}</span>
                <span className="vr-menu-meta">{piece[2][piece[2].length - 1][1]}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {selected === null ? (
        <div className="vr-empty">Pick a piece to see which of its versions your instance receives.</div>
      ) : (
        <>
          <div className="vr-head">
            <span>{displayName} versions</span>
            <span className="vr-head-axis">Activepieces releases that receive them</span>
          </div>

          <div className="vr-rows">
            {groups.map((group) => {
              const status = statusOf(group);
              const left = toPercent(group[2]);
              const right = toPercent(group[3]);
              return (
                <div className="vr-row" key={group[0]}>
                  <div className="vr-label">
                    <span className="vr-name">{versionRange(group)}</span>
                    <span className={status.on ? 'vr-status vr-status-on' : 'vr-status vr-status-off'}>{status.text}</span>
                  </div>
                  <div className="vr-track">
                    <div
                      className={[
                        'vr-bar',
                        status.on ? 'vr-bar-on' : 'vr-bar-off',
                        group[3] === lastIndex ? 'vr-bar-open' : '',
                      ].join(' ')}
                      title={`${group[4]} ${group[4] === 1 ? 'version' : 'versions'}, ${releases[group[2]]} to ${releases[group[3]]}`}
                      style={{ left: `${left}%`, width: `${Math.max(right - left, 1)}%` }}
                    />
                    <div className="vr-marker" style={{ left: `${toPercent(releaseIndex)}%` }} />
                  </div>
                </div>
              );
            })}

            <div className="vr-row vr-row-axis">
              <div className="vr-label" />
              <div className="vr-axis">
                {ticks.map(({ release, index }) => (
                  <span className="vr-tick" key={release} style={{ left: `${toPercent(index)}%` }}>
                    {release}
                  </span>
                ))}
              </div>
            </div>
          </div>

          <label className="vr-control">
            <span className="vr-control-label">Your instance version</span>
            <input
              className="vr-slider"
              type="range"
              min={0}
              max={lastIndex}
              step={1}
              value={releaseIndex}
              onChange={(event) => setReleaseIndex(Number(event.target.value))}
            />
            <span className="vr-control-value">{instance}</span>
          </label>

          <div className="vr-result">{summary()}</div>
        </>
      )}

      <div className="vr-footnote">
        From the Activepieces piece registry, releases {releases[0]} to {releases[lastIndex]}.
      </div>
    </div>
  );
};

